addTerms([
 {id:"mystical-body",t:"Mystical Body of Christ",la:"Corpus Christi mysticum",d:"Ecclesiology",b:"The Church as Christ's body, with Christ as Head and the faithful as members.",p:"The Church, one body of which Christ is Head by order, perfection and power (ST III q.8 a.1); identified with the Catholic Church in which the Church of Christ subsists (LG 8; Mystici Corporis, 1943).",ex:"\"You are the body of Christ\" (1 Cor 12:27).",where:"ST III q.8",ccc:"787–796",conf:"A merely invisible fellowship of believers.",rel:["grace"],lesson:"t14",alias:["Mystical Body","body of Christ"]},
 {id:"subsistit",t:"Subsistit in",la:"subsistit in",d:"Ecclesiology",b:"\"Subsists in\": the Church of Christ subsists in the Catholic Church, while elements of sanctification are found outside it.",p:"Lumen Gentium 8's formula: the one Church of Christ continues to exist fully only in the Catholic Church, governed by Peter's successor and the bishops in communion with him; elements of truth and sanctification outside belong to it by right (UR 3; CDF Responsa, 2007).",ex:"Baptism among Protestants is a true element of the one Church.",where:"LG 8",ccc:"816–819",conf:"The view that the Church of Christ is a sum of all denominations.",rel:["mystical-body"],lesson:"t14",alias:["subsistit in","subsists in"]},
 {id:"infallibility",t:"Papal infallibility",la:"infallibilitas",d:"Ecclesiology",b:"The pope's protection from error when he defines a doctrine of faith or morals ex cathedra.",p:"Defined at Vatican I (Pastor Aeternus, 1870, ch. 4): when the Roman Pontiff, as shepherd and teacher of all Christians, by his supreme apostolic authority defines a doctrine of faith or morals to be held by the whole Church, he enjoys the infallibility Christ willed his Church to have.",ex:"The definitions of 1854 and 1950.",where:"Pastor Aeternus ch. 4",ccc:"891",conf:"Impeccability, or every papal statement.",rel:["magisterium"],lesson:"t14",alias:["infallibility","infallible","ex cathedra"]},
 {id:"particular-judgment",t:"Particular judgment",la:"iudicium particulare",d:"Eschatology",b:"Each person's judgment immediately at death.",p:"At death the soul receives its recompense at once, unless an obstacle (venial sin or debt of punishment) delays the reward (Suppl. q.69 a.2; Benedict XII, Benedictus Deus, 1336; CCC 1022).",ex:"\"This day thou shalt be with me in paradise\" (Luke 23:43).",where:"Suppl. q.69 a.2",ccc:"1021–1022",conf:"The general judgment at the end of time.",rel:["beatific-vision"],lesson:"t15",alias:["particular judgment"]},
 {id:"purgatory",t:"Purgatory",la:"purgatorium",d:"Eschatology",b:"Final purification of those who die in God's grace but are not yet fully purified.",p:"A state of purification after death for the saved (Florence, 1439; Trent, Session 25; CCC 1030–1032), helped by the prayers and Masses of the living.",ex:"Praying for the dead (2 Macc 12:46).",where:"Suppl. Appendix; De rationibus fidei c.9",ccc:"1030–1032",conf:"A second chance for the unrepentant.",rel:["particular-judgment"],lesson:"t15",alias:["purgatory"]},
 {id:"canon-law",t:"Canon law",la:"ius canonicum",d:"Canon law",b:"The Church's own legal system.",p:"The body of laws of the Catholic Church; for the Latin Church the 1983 Code of Canon Law (CIC), for the Eastern Catholic Churches the 1990 Code of Canons of the Eastern Churches (CCEO); its supreme law is the salvation of souls (c. 1752).",ex:"Canon 11 on who is bound by Church law.",where:"ST I-II qq.90–97",ccc:"",conf:"Civil law.",rel:["law"],lesson:"t16",alias:["canon law","Code of Canon Law","canonical"]},
 {id:"epikeia",t:"Epikeia (equity)",la:"epikeia",d:"Canon law",b:"Following the lawgiver's intention when the letter of a law would defeat its purpose in an unforeseen case.",p:"A part of justice by which one departs from the letter of the law to follow justice and the common good intended by the lawgiver (ST II-II q.120 a.1).",ex:"Breaking a rule against opening the city gates to let in citizens fleeing an enemy (Thomas's example, I-II q.96 a.6).",where:"ST II-II q.120",ccc:"",conf:"Ignoring inconvenient laws.",rel:["justice","law"],lesson:"t16",alias:["epikeia","equity"]}
]);

